#!/usr/bin/env python3
from pathlib import Path
import base64, hashlib, math, subprocess, sys, tempfile

PATCH_SHA = "5d45f55da9667b1fdb262a178a193a95f6c35136c4d8bec54165dbe525af1fca"
PATCH_B64 = """"""
PRE = {'app/src/main/assets/shaders/motionv2/rcd26489_populate.glsl': '3e572712dfad2fc49d1ef2fb04ac42bfc64e329ffcddbaaea8483c43d8693b43', 'app/src/main/assets/shaders/motionv2/short_highlight_bayer_recover.glsl': 'c5c9f9dcbe6ce730b94f74e3a56361ddfcf9c3ac35b6113cdb1eae6565edae0a', 'app/src/main/java/com/particlesdevs/photoncamera/processing/opengl/postpipeline/MotionV2CfaInput.java': '3305c3c98ae14fa2fc45336506a61d90c67466182e0ee2b03fd4130443b26517', 'app/src/main/java/com/particlesdevs/photoncamera/processing/opengl/postpipeline/MotionV2RcdDemosaic.java': '7c205e683a6a86ebf02fee88ea8e25e2ec6a4758dcc2e37f23081d5e16274a8c', 'app/src/main/java/com/particlesdevs/photoncamera/processing/opengl/postpipeline/PostPipeline.java': 'd9dd382710da5251ca403557b1fa9bc7a9fc1bf0bb3a9409066c3f86406b21b2', 'app/src/main/java/com/particlesdevs/photoncamera/processing/processor/HdrxProcessor.java': '66665dc94ecdb9c253730e760abd368df21b53aa662d16b694e135873f488a03', 'app/src/main/java/com/particlesdevs/photoncamera/processing/processor/MotionV2CfaReconstruction.java': '55d8a98332662f8866e2b9b4c4d7fb060619430f899323685f33e1823530aa12', 'app/src/main/java/com/particlesdevs/photoncamera/processing/processor/MotionV2Merger.java': '0eaf10a20627b3a8e94a9f5664214999edb4273c48db5b571d0e77fe3ae0f002'}
POST = {'app/src/main/assets/shaders/motionv2/highlight_provenance_init.glsl': 'ccb2374fc52cfe3255480769e2a27f5d974bf401d64ff29ca21287a3f4458c89', 'app/src/main/assets/shaders/motionv2/rcd26489_populate.glsl': '60975a19cadd093114455c1f31a6b09b504a78cc7bb14daa4a2a7df5d82fd821', 'app/src/main/assets/shaders/motionv2/short_highlight_bayer_recover.glsl': '0cf29e6c9665f47a3669dd34413588d4a28557ea40dc5bf9a77af2d06c95be6a', 'app/src/main/java/com/particlesdevs/photoncamera/processing/opengl/postpipeline/MotionV2CfaInput.java': '34e3be4e1fc01cad8462fa0a9a63a210be891c35978dc300b9c9f61d9bd64151', 'app/src/main/java/com/particlesdevs/photoncamera/processing/opengl/postpipeline/MotionV2RcdDemosaic.java': 'd7530dde2fe75bea616683f18c08918e583381e7baaaa3feb393cc3a4b823a7f', 'app/src/main/java/com/particlesdevs/photoncamera/processing/opengl/postpipeline/PostPipeline.java': '8efefe8797086526ad5985f5655f3a28fb8e00ac721c9cb3a92ec083b1387f57', 'app/src/main/java/com/particlesdevs/photoncamera/processing/processor/HdrxProcessor.java': '42ce1234baa5e27ed0b31fb11660c27da0fd3e87102a383ec05b158678634d78', 'app/src/main/java/com/particlesdevs/photoncamera/processing/processor/MotionV2CfaReconstruction.java': '41378fbe06490b1e8d85da1cacfa9f7783760098b2826bbcca9f8c378838fd62', 'app/src/main/java/com/particlesdevs/photoncamera/processing/processor/MotionV2Merger.java': 'fe256b995e8a4a56ac36846d52a8ef33b18647014226f2ecc125db5ec7282c56'}
NEW_FILE = "app/src/main/assets/shaders/motionv2/highlight_provenance_init.glsl"

def sha_bytes(b): return hashlib.sha256(b).hexdigest()
def sha_file(p): return sha_bytes(Path(p).read_bytes())
def fail(msg): raise SystemExit("FAIL: "+msg)

def model_scene_gain(p50,p90,reference_energy):
    gain50=0.050/max(p50,1e-6); gain90=0.18/max(p90,1e-6)
    candidate=math.sqrt(max(1.0,gain50)*max(1.0,gain90))
    return max(1.0,min(candidate,16.0))

def model_observable(support,error,structure):
    return support>=12.0 and error<=0.12 and structure>=0.08

def self_test():
    a=model_scene_gain(0.008,0.045,0.8); b=model_scene_gain(0.008,0.045,25.0)
    if abs(a-b)>1e-7: fail("exposure energy still has veto authority")
    if not model_observable(20,0.05,0.20): fail("valid structured short correspondence rejected")
    if model_observable(20,0.05,0.01): fail("flat textureless short correspondence self-certified")
    if model_observable(20,0.30,0.20): fail("high-residual wrong short correspondence self-certified")
    patch=base64.b64decode(PATCH_B64)
    if sha_bytes(patch)!=PATCH_SHA: fail("embedded patch hash mismatch")
    text=patch.decode("utf-8")
    for token in (
      "IRIS_26492_SINGLE_SCENE_BODY_EXPOSURE_AUTHORITY",
      "IRIS_26492_EXPLICIT_HIGHLIGHT_PROVENANCE_INIT",
      "IRIS_26492_SHORT_OBSERVABILITY_RING",
      "IRIS_26492_EXPLICIT_PROVENANCE_SHORT_VALIDATION",
      "IRIS_26492_CENSORED_PACKED_NEUTRAL_LOWER_BOUND",
      "IRIS_26492_RCD_PROVENANCE_CONSUMER_ONLY",
      "highlightProvenanceR8UI",
      "exposureEnergyHasVeto=false"):
        if token not in text: fail("missing architecture token "+token)
    print("26492 TRANSFORM SELF-TEST PASS singleExposureAuthority=true explicitProvenance=true observableShort=true rcdConsumerOnly=true")

def apply(root):
    root=Path(root)
    version=(root/"app/version.properties").read_text()
    if "VERSION_NAME=0.9726491" not in version or "VERSION_BUILD=26491" not in version:
        fail("target is not exact 26491 version state")
    for rel,expected in PRE.items():
        p=root/rel
        if not p.is_file(): fail("missing 26491 input "+rel)
        actual=sha_file(p)
        if actual!=expected: fail(f"26491 pre-hash mismatch {rel} actual={actual} expected={expected}")
    if (root/NEW_FILE).exists(): fail("26492 provenance shader already exists")
    patch=base64.b64decode(PATCH_B64)
    if sha_bytes(patch)!=PATCH_SHA: fail("embedded patch hash mismatch")
    with tempfile.NamedTemporaryFile(prefix="26492_",suffix=".patch",delete=False) as f:
        f.write(patch); tmp=Path(f.name)
    try:
        subprocess.run(["git","apply","--check",str(tmp)],cwd=root,check=True)
        subprocess.run(["git","apply",str(tmp)],cwd=root,check=True)
    finally:
        try: tmp.unlink()
        except FileNotFoundError: pass
    for rel,expected in POST.items():
        p=root/rel
        if not p.is_file(): fail("missing 26492 output "+rel)
        actual=sha_file(p)
        if actual!=expected: fail(f"26492 post-hash mismatch {rel} actual={actual} expected={expected}")
    print("26492 TRANSFORM PASS files=9 exact26491Base=true authorityProvenanceContract=true")

if __name__ == "__main__":
    if len(sys.argv)==2 and sys.argv[1]=="--self-test": self_test()
    elif len(sys.argv)==2: self_test(); apply(sys.argv[1])
    else: fail("usage: transform_26492_authority_provenance_v1.py --self-test | <root>")
